<div class="page-actions"><p class="text-muted mb-0">Centraliza cámaras, alarmas, sensores y botones de pánico.</p><button class="btn btn-primary" data-modal-open="deviceModal">+ Registrar dispositivo</button></div><div class="device-grid"><?php if(!$devices):?><div class="card empty-state">No hay dispositivos registrados.</div><?php endif;?><?php foreach($devices as $device):?><article class="device-card"><div class="device-icon type-<?= e($device['type']) ?>"><?= $device['type']==='camara'?'◉':($device['type']==='alarma'?'⚠':'⌁') ?></div><div><div class="d-flex justify-content-between"><h2><?= e($device['name']) ?></h2><span class="status-dot <?= e($device['status']) ?>"></span></div><p><?= e(ucfirst(str_replace('_',' ',$device['type']))) ?> · <?= e($device['location']?:'Sin ubicación') ?></p><small>Propietario: <?= e($device['owner_name']) ?> · Protocolo <?= e(strtoupper($device['protocol'])) ?></small><div class="device-meta"><span><?= $device['events_count'] ?> eventos</span><span><?= $device['last_seen_at']?'Última señal '.e(date('d/m H:i',strtotime($device['last_seen_at']))):'Sin eventos' ?></span></div><form class="quick-event" method="post" action="<?= url('dispositivos/'.$device['id'].'/evento') ?>"><?= csrf_field() ?><input type="hidden" name="event_type" value="Alerta manual"><input type="hidden" name="severity" value="advertencia"><button class="btn btn-outline-danger btn-sm">Generar alerta de prueba</button></form></div></article><?php endforeach;?></div><section class="card mt-4"><div class="card-header"><div><h2>Eventos recientes</h2><p>Actividad recibida desde los dispositivos</p></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Dispositivo</th><th>Evento</th><th>Severidad</th><th>Fecha</th></tr></thead><tbody><?php if(!$events):?><tr><td colspan="4" class="empty-state">No hay eventos.</td></tr><?php endif;?><?php foreach($events as $event):?><tr><td><?= e($event['device_name']) ?></td><td><?= e($event['event_type']) ?></td><td><span class="priority priority-<?= $event['severity']==='critica'?'critica':($event['severity']==='advertencia'?'alta':'baja') ?>"><?= e($event['severity']) ?></span></td><td><?= e(date('d/m/Y H:i',strtotime($event['created_at']))) ?></td></tr><?php endforeach;?></tbody></table></div></section>
<div class="modal" id="deviceModal" hidden><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><h2>Nuevo dispositivo</h2><button data-modal-close>×</button></div><form method="post" action="<?= url('dispositivos') ?>"><?= csrf_field() ?><div class="modal-body"><div class="row g-3"><div class="col-md-7"><label class="form-label">Nombre</label><input class="form-control" name="name" placeholder="Cámara acceso principal" required></div><div class="col-md-5"><label class="form-label">Tipo</label><select class="form-select" name="type"><option value="camara">Cámara</option><option value="alarma">Alarma</option><option value="sensor">Sensor</option><option value="boton_panico">Botón de pánico</option><option value="otro">Otro</option></select></div><div class="col-12"><label class="form-label">Ubicación</label><input class="form-control" name="location"></div><div class="col-md-4"><label class="form-label">Protocolo</label><select class="form-select" name="protocol"><option value="manual">Manual</option><option value="rtsp">RTSP</option><option value="onvif">ONVIF</option><option value="http">HTTP</option><option value="mqtt">MQTT</option></select></div><div class="col-md-8"><label class="form-label">URL de conexión</label><input class="form-control" name="connection_url" placeholder="Opcional"></div></div><div class="alert alert-warning mt-3 mb-0">Las credenciales no deben incluirse en la URL. En producción, integra cada fabricante mediante un conector seguro del servidor.</div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-modal-close>Cancelar</button><button class="btn btn-primary">Registrar</button></div></form></div></div></div>

